let selected = game.foundryDumpingGround.getSelected();
let result = await game.succ.boostLowerTraitDialog(selected[0].actor, "boost");
if (!result) { return; }
let boostData = {boost: result};
game.foundryDumpingGround.addCondition("boost", selected, {effectOptions: boostData, allowDuplicates: true});
